基本结构create or replace function somefunc() returns varchar as $$declare   name varchar := &#x27;wangzhen&#x27;;begin   return name;end   $$ language plpgsql;

$$作用
函数代码在function中实际上为一个字符串，代码1和代码2等价，但代码中字符串的单引号需要写两个进行转义。
  -- 代码1create or replace function somefunc() returns varchar as $$declare   name varchar := &#x27;wangzhen&#x27;;begin   return name;end   $$ language plpgsql;

  --代码2create or replace function somefunc() returns varchar as &#x27;declare   name varchar := &#x27;&#x27;wangzhen&#x27;&#x27;;begin   return name;end   &#x27; language plpgsql;
“美元符引用”书写字符串常量，使单引号、反斜线、$符等按照字面值进行解释，不需要写两个或在4个或着更多进行转义，代码3和代码4等价。
  --代码3create or replace function somefunc() returns varchar as $$declare   name varchar := &#x27;wangzhen&#x27;&#x27;blog&#x27;;begin   return name;end   $$ language plpgsql;
  --代码4create or replace function somefunc() returns varchar as $$declare   name varchar := $tag$wangzhen&#x27;blog$tag$;begin   return name;end   $$ language plpgsql;

$中间可以包含可选的标签，但是标签要成对出现，且大小写敏感。代码5和代码6和代码7等价。
  --代码5create or replace function somefunc() returns varchar as $body$declare   name varchar := $tag$wangzhen&#x27;blog$tag$;begin   return name;end   $body$ language plpgsql ;
  --代码6create or replace function somefunc() returns varchar as $func$declare   name varchar := $$wangzhen&#x27;blog$$;begin   return name;end   $func$ language plpgsql ;
  --代码7create or replace function somefunc() returns varchar as $$declare   name varchar := &#x27;wangzhen&#x27;&#x27;blog&#x27;;begin   return name;end   $$ language plpgsql ;

代码块
块名可选，代码8和9等价
  --代码8create or replace function somefunc() returns varchar as$$&lt;&lt;outblock&gt;&gt;declare    name varchar := &#x27;wangzhen&#x27;;begin   return outblock.name;end;        $$ language plpgsql; 
  --代码9create or replace function somefunc() returns varchar as$$declare    name varchar := &#x27;wangzhen&#x27;;begin   return name;end;        $$ language plpgsql; 

块可嵌套，内层同名变量覆盖外层同名变量，可通过指定块名引用。
 --代码10create or replace function somefunc() returns varchar as$$&lt;&lt;outblock&gt;&gt;declare    name varchar := &#x27;wangzhen&#x27;;begin   &lt;&lt;innerblock&gt;&gt;   declare       name varchar := &#x27;xiaozhang&#x27;;   begin      outblock.name = innerblock.name;   end;      return outblock.name;end;        $$ language plpgsql; 
 abase=# select somefunc(); somefunc  ----------- xiaozhang

函数体是一个隐藏的块，块名是函数名。
  --代码11create or replace function somefunc(name varchar) returns varchar as$$&lt;&lt;outblock&gt;&gt;declare    name varchar := somefunc.name;begin   return outblock.name;end;        $$ language plpgsql; 
  abase=# select somefunc(&#x27;xiaoli&#x27;); somefunc ---------- xiaoli(1 row)

命名参数
在函数声明时直接命名参数
  --代码12create or replace function somefunc(newname varchar) returns varchar as$$declare    name varchar := newname;begin   return name;end;        $$ language plpgsql; 

使用别名和美元符号
  --代码13create or replace function somefunc(varchar,varchar) returns varchar as$$declare    newname alias for $1;   name varchar := newname;   name2 varchar := $2;begin   return name;end;        $$ language plpgsql; 

执行sql
没有返回结果的SQL可以直接执行
  --代码14create or replace function somefunc2() returns void as$$begin   create table test1 (n_id integer,c_mc varchar(300));   insert into test1 (n_id,c_mc) values (1,&#x27;wangzhen&#x27;);end;        $$ language plpgsql; 

不需要返回结果的select可以通过perform执行。perform替换select
  --代码15create or replace function somefunc3() returns void as$$begin   perform * from test1;end;        $$ language plpgsql; 
  --代码16create or replace function somefunc3() returns void as$$begin   perform somefunc();   --perform 怎么处理with和其他复杂查询？end;        $$ language plpgsql; 

执行动态拼接SQL
  --代码17create or replace function somefunc3() returns void as$$declarevar_sql varchar := &#x27;insert into test1 values (0,&#x27;||quote_literal(&#x27;admin&#x27;)||&#x27;)&#x27;;begin   execute var_sql;   execute format(&#x27;insert into %I values (%L,%L)&#x27;,&#x27;test1&#x27;,2,&#x27;xiaoniu&#x27;);end;        $$ language plpgsql; 

返回结果
返回结果分为返回标量（单行）和返回结果集合（多行）两种情况。


返回标量
  -- 代码18-- 返回单行intcreate or replace function somefunc4()returns int as$$begin   return 100;end   $$ language plpgsql;
  -- 代码19-- 通过out参数返回create or replace function somefunc4(out v1 integer) as$$begin   v1 := 100;end  $$ language plpgsql;-- OUT 返回DROP FUNCTION if exists update_products(character varying,character varying);create or replace function update_products(main_table_name varchar, child_table_name varchar, OUT success int, OUT error int) returns setof record as$body$declare  rec_record record;BEGINsuccess := 0;  for rec_record in select * from loans_category loop    success := success + 1;  end loop;  return next;  // r := row(main_table_name, child_table_name);  返回行数据END;$body$ language plpgsql;
  -- 代码20-- 返回单行record 复合类型create or replace function somefunc4(id integer,mc varchar) returns record as$$declare    r record;begin   r := row(id,mc);   return r;end  $$ language plpgsql;

SETOF 作用

返回结果集合（多行）时，需要使用SETOF指定

  --代码21--返回单列多行create or replace function somefunc5()returns setof int as$$declareid int;begin   for id in select n_id from test1    loop      return next id;   end loop;   return;  end   $$ language plpgsql;

  结果：
  abase=# select somefunc5(); somefunc5 -----------         1         1         0         0         2(5 rows)

返回结果集
  -- 代码22-- 通过out参数返回-- returns setof record  可以省略create or replace function somefunc6(out id integer,out name varchar)returns setof record as $$declare    r record;begin   for r in select n_id,c_mc from test1    loop      id := r.n_id;      name := r.c_mc;      return next;   end loop; end$$ language plpgsql;

  结果：
  abase=# select * from somefunc6() ; id |   name    ----+-----------  1 | wangzhen  1 | xiaozhang  0 | admin  0 | admin  2 | xiaoniu(5 rows)
  -- 代码23-- 通过return next 返回自定义类型create type test_rs as (id int,mc varchar);create or replace function somefunc7()returns setof test_rs as $$declare   r test_rs%rowtype;begin   for r in select n_id,c_mc from test1   loop      return next r;   end loop;   return;end$$ language plpgsql;
  -- 代码24-- 通过return query 返回自定义类型create or replace function somefunc7()returns setof test_rs as $$declare   r test_rs%rowtype;begin   return query select n_id,c_mc from test1;   return;end$$ language plpgsql;
  -- 代码25-- 通过return next返回表类型create or replace function somefunc7()returns setof test1 as $$declare   r test1%rowtype;begin   for r in select n_id,c_mc from test1   loop      return next r;   end loop;   return;end$$ language plpgsql;
  -- 代码26-- 通过拼接sql  return next 返回自定义类型create or replace function somefunc7()returns setof test_rs as $$declare   r test_rs%rowtype;begin   for r in execute &#x27;select n_id,c_mc from test1&#x27;   loop      return next r;   end loop;   return;end$$ language plpgsql;
  -- 代码26-- 通过拼接sql  return query 返回自定义类型create or replace function somefunc7()returns setof test_rs as $$declare   r test_rs%rowtype;begin   return query execute &#x27;select n_id,c_mc from test1&#x27;;   return;end$$ language plpgsql;


返回结果集时PostgreSQL 9.5.4，需要使用自定义类型或表类型制定返回类型，不能用record匿名类型。

循环判断
LOOP循环
  create or replace function testloop1() returns void as$$declare    count int :=0;begin    loop       exit when count &gt;=100;       count := count + 1;       raise notice &#x27;count is %&#x27;,count;    end loop;end$$ language plpgsql ;

WHILE循环
  create or replace function testloop2() returns void as$$declare    count int :=0;begin    while count &lt;100 loop       count := count + 1;       raise notice &#x27;count is %&#x27;,count;    end loop;end$$ language plpgsql ;

FOR循环
  create or replace function testloop3() returns void as$$begin  for i in 1..100 loop     raise notice &#x27;count is %&#x27;,i;  end loop;end$$ language plpgsql;
  create or replace function testloop4() returns void as$$begin  for i in reverse 100..1 by 2 loop      raise notice &#x27;count is %&#x27;,i;  end loop;end$$ language plpgsql;

FOREACH循环
  create or replace function testloop5()returns void as$$declare  v_arr int[]:= array[1,2,3,4,5];  i int;begin  foreach i in array v_arr loop      raise notice &#x27;count is %&#x27;,i;  end loop;end$$ language plpgsql;

参考资料-- record/%ROWTYPE类型返回-- 返回结果集合（多行）时，需要使用SETOF指定. -- returns record || returns setof recordDROP FUNCTION if exists update_products(character varying,character varying);create or replace function update_products(main_table_name varchar, child_table_name varchar) returns setof record as$body$declare  rec_row loans_category%rowtype;  rec_record record;BEGIN  for rec_row in select * from loans_category loop    return next rec_row;  end loop;  for rec_record in select * from loans_category loop    return next rec_record;  end loop;  return next;END;$body$ language plpgsql;select * from update_products();

to_char(timestamp, text)	text	把时间戳转换成字串  to_char(current_timestamp, &#x27;HH12:MI:SS&#x27;)to_char(interval, text)	text	把时间间隔转为字串  to_char(interval &#x27;15h 2m 12s&#x27;, &#x27;HH24:MI:SS&#x27;)to_char(int, text)	text	把整数转换成字串  to_char(125, &#x27;999&#x27;)to_char(double precision, text)	text	把实数/双精度数转换成字串  to_char(125.8::real, &#x27;999D9&#x27;)to_char(numeric, text)	text	把 numeric 转换成字串  to_char(-125.8, &#x27;999D99S&#x27;)to_date(text, text)	date	把字串转换成日期  to_date(&#x27;05 Dec 2000&#x27;, &#x27;DD Mon YYYY&#x27;)to_timestamp(text, text)	timestamp with time zone  把字串转换成时间戳  to_timestamp(&#x27;05 Dec 2000&#x27;, &#x27;DD Mon YYYY&#x27;)to_timestamp(double precision)	timestamp with time zone  把 UNIX 纪元转换成时间戳	to_timestamp(200120400)to_number(text, text)	numeric	把字串转换成 numeric  to_number(&#x27;12,454.8-&#x27;, &#x27;99G999D9S&#x27;)


decode 用 case when a&#x3D;1 then b else c end
最后一天  to_date(? +’1 mons’::interval,’yyyy-mm’) -1
第一天 to_date(?,’yyyy-mm’) , date_trunc(‘month’,?)
字段别名 加上 as
子查询一定要用别名 
取子树 ,postgresql需人自己写函数，或者用一些有结构特性字段如1.1,1.1.1,1.1.2  来代替
trunc(im.createdate) 可改为date_trunc(‘day’,createdate) ，date_trunc 与oracle的trunc很像,还可以  SELECT date_trunc(&#39;hour&#39;, TIMESTAMP &#39;2001-02-16 20:38:40&#39;);   Result: 2001-02-16 20:00:00+00  SELECT date_trunc(&#39;year&#39;, TIMESTAMP &#39;2001-02-16 20:38:40&#39;);   Result: 2001-01-01 00:00:00+00
postgres-当日, 带时分秒,now()  oracle- sysdate
postgres-当日,不带时分秒current_date,oracle  to_char(sysdate,’YYYY-MM-DD) 
nvl 全部替换成 coalesce  如 coalesce(im.invoiceamount,0)
小数据位数round,例保留一位小数 用select round(2.16,1)  Result: 2.2 会四舍五入
转志数据类型用::数据类型,如to_number() 改用::numeric 
如果取子树,不包含自身,使用函数时,第二个参数取2,如,getorgantree(?,2)
项目树函数第一个参数是id,其他的如果地区编码,税务机关分别有参数为编码的,如get..tree(code,level),参数为id的,如get..treebyid(id,level)
修改表时,表名不能带别名,如update taxpayer_cognizance_invoice tc   这里taxpayer_cognizance_invoice 不能带别名tc

